package com.andye.warmod.radar;import com.andye.warmod.antiair.AntiAirMissileVariant;import com.andye.warmod.warhead.WarheadPayloadType;import java.util.*;public record RadarTrackSnapshot(UUID trackId,RadarTrackKind kind,UUID ownerPlayerId,String ownerDisplayName,Optional<WarheadPayloadType> strategicPayloadType,Optional<AntiAirMissileVariant> interceptorVariant,RadarTrackPhase phase,Optional<RadarCarrierPlanSnapshot> carrierPlan,List<RadarTerminalPlanSnapshot> terminalPlans,Optional<RadarInterceptorPlanSnapshot> interceptorPlan){public RadarTrackSnapshot{terminalPlans=List.copyOf(terminalPlans);}public RadarTrackSnapshot(UUID id,RadarTrackKind kind,UUID owner,String name,Optional<WarheadPayloadType> payload,Optional<AntiAirMissileVariant> variant,RadarTrackPhase phase,Optional<RadarCarrierPlanSnapshot> carrier,Optional<RadarTerminalPlanSnapshot> terminal,Optional<RadarInterceptorPlanSnapshot> interceptor){this(id,kind,owner,name,payload,variant,phase,carrier,terminal.map(List::of).orElseGet(List::of),interceptor);}public Optional<RadarTerminalPlanSnapshot> terminalPlan(){return terminalPlans.stream().findFirst();}}
